INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20LDAYO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A ceramics studio uses $\\frac{7}{4}$ pounds of clay for every $3$ bowls it produces. How many pounds of clay are needed to produce $12$ bowls?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$9$"},{"key":"C","text":"$21$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $\\frac{7}{4}$ pounds of clay produces $3$ bowls, the unit rate is $\\frac{7}{4} \\div 3 = \\frac{7}{12}$ pounds per bowl. For $12$ bowls: $\\frac{7}{12} \\times 12 = 7$ pounds. Alternatively, $12$ bowls is $4$ groups of $3$ bowls, so the clay needed is $4 \\times \\frac{7}{4} = 7$ pounds. The answer $21$ results from multiplying $\\frac{7}{4}$ by $12$ without dividing by $3$, incorrectly treating $\\frac{7}{4}$ as the per-bowl rate. The answer $28$ results from multiplying $7$ by $4$ without accounting for the fraction in the original ratio.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM215A9IE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A set of $5$ quiz scores is: $67, 73, 81, 81, 88$. What is the median of these scores?', NULL, $lyceon_json$[{"key":"A","text":"$73$"},{"key":"B","text":"$77$"},{"key":"C","text":"$78$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'D', NULL, E'The scores in order are $67, 73, 81, 81, 88$. With $5$ values, the median is the $3$rd value, which is $81$. The value $77$ results from averaging $73$ and $81$ as though there were an even number of data points. The value $73$ comes from selecting the $2$nd value instead of the $3$rd. The value $78$ comes from computing the mean of all five values divided incorrectly.', $lyceon_json${"D":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM219GUOY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has a radius of $9$ inches. What is the length of an arc subtended by a central angle of $140^\\circ$?', NULL, $lyceon_json$[{"key":"A","text":"$7\\pi$ inches"},{"key":"B","text":"$9\\pi$ inches"},{"key":"C","text":"$14\\pi$ inches"},{"key":"D","text":"$7$ inches"}]$lyceon_json$::jsonb, 'A', NULL, E'Arc length is given by $s = \\frac{\\theta}{360^\\circ} \\times 2\\pi r$. Substituting gives $s = \\frac{140}{360} \\times 2\\pi(9) = \\frac{7}{18} \\times 18\\pi = 7\\pi$ inches. The value $9\\pi$ results from using $180^\\circ$ instead of $140^\\circ$ (i.e., computing a semicircle arc). The value $14\\pi$ comes from using the diameter ($18$) instead of the radius in the formula, or equivalently computing $\\frac{140}{360} \\times 2\\pi(18)$. The value $7$ omits the factor of $\\pi$, computing only the numerical coefficient.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24PIYF9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 14x + 4y - 11 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'To find the radius, rewrite the equation in standard form by completing the square. Group the $x$-terms and $y$-terms: $(x^2 - 14x) + (y^2 + 4y) = 11$. Complete the square for $x$: $x^2 - 14x + 49 = (x - 7)^2$. Complete the square for $y$: $y^2 + 4y + 4 = (y + 2)^2$. Add $49$ and $4$ to both sides: $(x - 7)^2 + (y + 2)^2 = 11 + 49 + 4 = 64$. The equation is now in the form $(x - h)^2 + (y - k)^2 = r^2$, so $r^2 = 64$ and $r = 8$. A common error is giving $r^2 = 64$ as the answer instead of $r = 8$. Another error is forgetting to add the completing-the-square constants to the right side, yielding $r^2 = 11$ and $r = \\sqrt{11}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25DYNFP', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'The system of inequalities $y \\leq -\\frac{5}{3}x + 17$ and $y \\geq \\frac{2}{3}x - 4$ defines a region in the $xy$-plane. Which of the following points lies within this region?', NULL, $lyceon_json$[{"key":"A","text":"$(15, 2)$"},{"key":"B","text":"$(9, 3)$"},{"key":"C","text":"$(6, 7)$"},{"key":"D","text":"$(12, 5)$"}]$lyceon_json$::jsonb, 'C', NULL, E'For the point $(6, 7)$: the first inequality gives $-\\frac{5}{3}(6) + 17 = -10 + 17 = 7$, and $7 \\leq 7$ is true. The second inequality gives $\\frac{2}{3}(6) - 4 = 4 - 4 = 0$, and $7 \\geq 0$ is true. So $(6, 7)$ satisfies both. For $(15, 2)$: $-\\frac{5}{3}(15) + 17 = -25 + 17 = -8$, and $2 \\leq -8$ is false. For $(9, 3)$: $-\\frac{5}{3}(9) + 17 = -15 + 17 = 2$, and $3 \\leq 2$ is false. For $(12, 5)$: $-\\frac{5}{3}(12) + 17 = -20 + 17 = -3$, and $5 \\leq -3$ is false.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25RZBTL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally costs $47$ dollars. During a sale, the price is reduced by $30\\%$. What is the sale price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$14.10$"},{"key":"B","text":"$17.00$"},{"key":"C","text":"$32.90$"},{"key":"D","text":"$61.10$"}]$lyceon_json$::jsonb, 'C', NULL, E'A $30\\%$ reduction means the sale price is $47 \\times (1 - 0.30) = 47 \\times 0.70 = 32.90$ dollars. Equivalently, the discount is $47 \\times 0.30 = 14.10$ dollars, so the sale price is $47 - 14.10 = 32.90$ dollars. The value $14.10$ is the amount of the discount, not the sale price. The value $61.10$ results from adding the $30\\%$ instead of subtracting it. The value $17.00$ comes from an arithmetic error in computing the discount.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25TJSJF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The ages, in years, of $7$ employees at a small firm are: $29, 31, 34, 37, 41, 45, 59$. What is the interquartile range of the employees'' ages?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'To find the interquartile range (IQR), first identify the quartiles. The median (Q2) is the $4$th value: $37$. The lower half is $29, 31, 34$, so Q1 is $31$. The upper half is $41, 45, 59$, so Q3 is $45$. The IQR is $Q3 - Q1 = 45 - 31 = 14$. A common error is computing the full range ($59 - 29 = 30$) instead of the interquartile range, or miscalculating Q1 and Q3 by including the median in both halves.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25Z0A1X', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bookstore sells hardcover books for 19 dollars each and paperback books for 11 dollars each. On a particular day, the store sold a total of 37 books and collected 511 dollars. How many hardcover books were sold?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$13$"},{"key":"C","text":"$17$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $h$ represent the number of hardcover books and $p$ the number of paperback books. The system is $h + p = 37$ and $19h + 11p = 511$. Substituting $p = 37 - h$ into the revenue equation gives $19h + 11(37 - h) = 511$, which simplifies to $19h + 407 - 11h = 511$, then $8h = 104$, so $h = 13$. The value $24$ is the number of paperback books, resulting from answering the wrong quantity. The value $9$ comes from incorrectly setting up the price equation with swapped coefficients. The value $17$ results from an arithmetic error when dividing $104$ by $8$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM265WS8R', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'If $y = 2x + 1$ and $x^2 + y^2 = 29$, what is the sum of all $x$-values that satisfy both equations?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{4}{5}$"},{"key":"B","text":"$\\frac{4}{5}$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $y = 2x + 1$ into $x^2 + y^2 = 29$: $x^2 + (2x + 1)^2 = 29$, which expands to $x^2 + 4x^2 + 4x + 1 = 29$, giving $5x^2 + 4x - 28 = 0$. By Vieta''s formulas, the sum of the roots is $-\\frac{b}{a} = -\\frac{4}{5}$. The distractor $\\frac{4}{5}$ results from a sign error in Vieta''s formula, forgetting the negative. The distractor $-2$ comes from finding only the negative root $x = -\\frac{14}{5}$ and rounding or miscalculating. The distractor $2$ comes from finding only the positive root $x = 2$ and assuming that is the complete answer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM269J338', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $9x + 7 > 61$?', NULL, $lyceon_json$[{"key":"A","text":"4"},{"key":"B","text":"5"},{"key":"C","text":"6"},{"key":"D","text":"7"}]$lyceon_json$::jsonb, 'D', NULL, E'Subtracting 7 from both sides gives $9x > 54$, so $x > 6$. Among the options, only $7$ is greater than $6$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM276T500', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town''s population was $6{,}300$ in 2018. By 2023, the population had increased to $7{,}938$. What was the approximate percent increase in population from 2018 to 2023?', NULL, $lyceon_json$[{"key":"A","text":"$20.6\\%$"},{"key":"B","text":"$26.0\\%$"},{"key":"C","text":"$16.4\\%$"},{"key":"D","text":"$79.4\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The percent increase is $\\frac{7{,}938 - 6{,}300}{6{,}300} \\times 100 = \\frac{1{,}638}{6{,}300} \\times 100 = 26.0\\%$. The value $20.6\\%$ comes from dividing the change by the final population ($\\frac{1{,}638}{7{,}938}$) instead of the original population. The value $16.4\\%$ results from computing the change incorrectly. The value $79.4\\%$ confuses the ratio $\\frac{6{,}300}{7{,}938}$ with the percent increase.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM281YVAU', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9a^2 - 49b^2}{3a + 7b}$?', NULL, $lyceon_json$[{"key":"A","text":"$3a + 7b$"},{"key":"B","text":"$3a - 7b$"},{"key":"C","text":"$9a - 49b$"},{"key":"D","text":"$\\frac{3a - 7b}{3a + 7b}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $9a^2 - 49b^2$ is a difference of squares: $(3a)^2 - (7b)^2 = (3a + 7b)(3a - 7b)$. Dividing by $(3a + 7b)$ cancels that factor, leaving $3a - 7b$. The distractor $3a + 7b$ confuses which factor remains after cancellation. The distractor $9a - 49b$ fails to recognize the difference-of-squares pattern and instead simply takes the square roots of the coefficients without properly factoring. The distractor $\\frac{3a - 7b}{3a + 7b}$ incorrectly retains the denominator after the common factor has already been canceled.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28MZZHX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher surveys a random sample of 900 registered voters in a state and finds that $47\\%$ plan to vote for Candidate X, with a margin of error of $\\pm 3.3\\%$ at a $95\\%$ confidence level. A second researcher surveys a random sample of 225 registered voters from the same state and finds that $52\\%$ plan to vote for Candidate X, with a margin of error of $\\pm 6.6\\%$ at the same confidence level. Which of the following conclusions is most justified?', NULL, $lyceon_json$[{"key":"A","text":"Neither survey provides sufficient evidence that Candidate X has majority support, because both confidence intervals include values below $50\\%$."},{"key":"B","text":"The second survey proves Candidate X has majority support because the sample proportion exceeds $50\\%$."},{"key":"C","text":"The first survey is invalid because its sample proportion is below $50\\%$."},{"key":"D","text":"The margin of error of the second survey is larger solely because its sample proportion is farther from $50\\%$."}]$lyceon_json$::jsonb, 'A', NULL, E'The first survey''s confidence interval is $47\\% \\pm 3.3\\%$, or $43.7\\%$ to $50.3\\%$, which includes values below $50\\%$. The second survey''s confidence interval is $52\\% \\pm 6.6\\%$, or $45.4\\%$ to $58.6\\%$, which also includes values below $50\\%$. Since both intervals contain values below the majority threshold, neither survey provides sufficient evidence of majority support. Claiming the second survey proves majority support because $52\\% > 50\\%$ ignores the margin of error. Calling the first survey invalid because its estimate is below $50\\%$ confuses a sample estimate with a flaw in methodology. The margin of error of the second survey is larger primarily because of the smaller sample size ($225$ vs. $900$), not because of the sample proportion''s distance from $50\\%$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28Q26X8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $34$ centimeters. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$17\\pi$ centimeters"},{"key":"B","text":"$34\\pi$ centimeters"},{"key":"C","text":"$68\\pi$ centimeters"},{"key":"D","text":"$289\\pi$ centimeters"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Substituting $d = 34$ gives $C = 34\\pi$ centimeters.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM298GBZD', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f(x) = -4x + 37$ models the number of gallons of water remaining in a tank after $x$ hours. What does the value $37$ represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The initial number of gallons in the tank"},{"key":"B","text":"The rate at which water drains per hour"},{"key":"C","text":"The number of hours until the tank is empty"},{"key":"D","text":"The number of gallons drained after one hour"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing the initial number of gallons in the tank. In the function $f(x) = -4x + 37$, the constant $37$ is the $y$-intercept, representing the value of $f(0)$, which is the number of gallons at time $x = 0$ (the start). The rate at which water drains per hour is represented by the coefficient $-4$, not by $37$. The number of hours until the tank is empty would be found by solving $-4x + 37 = 0$, which gives $x = \\frac{37}{4}$, a different quantity. The number of gallons drained after one hour is $|f(1) - f(0)| = 4$, not $37$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BMBJ6D', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, -3)$ and $(8, 15)$. What is the equation of this line in slope-intercept form?', NULL, $lyceon_json$[{"key":"A","text":"$y = 3x - 9$"},{"key":"B","text":"$y = 3x + 9$"},{"key":"C","text":"$y = -3x + 3$"},{"key":"D","text":"$y = 2x - 7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $y = 3x - 9$. The slope is $m = \\frac{15 - (-3)}{8 - 2} = \\frac{18}{6} = 3$. Using point-slope form with $(2, -3)$: $y - (-3) = 3(x - 2)$, which gives $y + 3 = 3x - 6$, so $y = 3x - 9$. The equation $y = 3x + 9$ has the correct slope but a sign error in the intercept calculation. The equation $y = -3x + 3$ uses the negative of the correct slope. The equation $y = 2x - 7$ comes from an arithmetic slip in computing the slope as $\\frac{18}{8}$ rounded incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BRU481', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $8x + 13 = 77$?', NULL, $lyceon_json$[{"key":"A","text":"6"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"11"}]$lyceon_json$::jsonb, 'C', NULL, E'Subtracting 13 from both sides gives $8x = 64$. Dividing both sides by 8 gives $x = 8$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EPRZRC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher wants to determine whether a new tutoring method improves exam scores. She recruits 140 volunteers and randomly assigns 70 to receive the new tutoring method and 70 to receive the standard method. At the end of the semester, the new-method group scores an average of 6 points higher on the final exam, a difference that is statistically significant. However, the volunteers were all enrolled in the same introductory course and chose to participate. Which of the following best describes a valid limitation of this study?', NULL, $lyceon_json$[{"key":"A","text":"Because the volunteers self-selected into the study, the results may not generalize to all students at the university."},{"key":"B","text":"Because the assignment to groups was random, the 6-point difference is definitely due to the tutoring method."},{"key":"C","text":"The study cannot support any causal claim because the participants were volunteers."},{"key":"D","text":"The study's conclusion is invalid because both groups were from the same course."}]$lyceon_json$::jsonb, 'A', NULL, E'Random assignment supports a causal conclusion among the participants, but because the participants are self-selected volunteers from a single course, the findings may not generalize to all students at the university. This is a valid limitation: the study has internal validity (causal inference within the sample) but limited external validity (generalizability). The claim that random assignment guarantees the difference is due to tutoring ignores the generalizability limitation and overstates certainty. Saying the study cannot support any causal claim is incorrect because random assignment does support causal inference within the study. Claiming the results are invalid because both groups are from the same course misunderstands the design; having both groups in the same course actually controls for course-level differences.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EX7BDI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A chemical solution requires $\\frac{11}{5}$ liters of solvent for every $\\frac{3}{7}$ kilogram of compound. If a researcher has $\\frac{9}{7}$ kilograms of compound, how many liters of solvent are needed?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '33/5', ARRAY['33/5', '6.6'], E'Set up a proportion using the given ratio. The rate of solvent per kilogram of compound is $\\frac{11/5}{3/7} = \\frac{11}{5} \\times \\frac{7}{3} = \\frac{77}{15}$ liters per kilogram. For $\\frac{9}{7}$ kilograms: $\\frac{77}{15} \\times \\frac{9}{7} = \\frac{693}{105} = \\frac{33}{5}$ liters. Alternatively, note that $\\frac{9}{7} \\div \\frac{3}{7} = 3$, so the researcher has exactly $3$ times the base amount of compound, requiring $3 \\times \\frac{11}{5} = \\frac{33}{5}$ liters.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F59PZF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 3 \\cdot 2^x$. What is the value of $g(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$24$"},{"key":"B","text":"$48$"},{"key":"C","text":"$81$"},{"key":"D","text":"$96$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 4$: $g(4) = 3 \\cdot 2^4 = 3 \\cdot 16 = 48$. The distractor $24$ comes from computing $3 \\cdot 2 \\cdot 4 = 24$, treating the exponent as multiplication. The distractor $81$ results from computing $3^4 = 81$, misinterpreting which base is raised to the power. The distractor $96$ comes from computing $3 \\cdot 2^5 = 96$, incorrectly using $x = 5$ instead of $x = 4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F7ZGAM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A spinner is divided into 11 equal sections, each labeled with a different integer from 1 through 11. If the spinner is spun once, what is the probability that it lands on a prime number?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{11}$"},{"key":"B","text":"$\\frac{4}{11}$"},{"key":"C","text":"$\\frac{6}{11}$"},{"key":"D","text":"$\\frac{3}{11}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The prime numbers from 1 through 11 are 2, 3, 5, 7, and 11, giving 5 primes out of 11 total sections. The probability is $\\frac{5}{11}$. The answer $\\frac{4}{11}$ results from incorrectly excluding 11 as a prime or including 1 as a non-prime replacement. The answer $\\frac{6}{11}$ comes from mistakenly counting 1 as prime. The answer $\\frac{3}{11}$ results from miscounting the primes in the range.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FQFFIR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $DEF$, the measure of angle $D$ is $53^\\circ$ and the measure of angle $E$ is $71^\\circ$. What is the measure of angle $F$?', NULL, $lyceon_json$[{"key":"A","text":"$34^\\circ$"},{"key":"B","text":"$56^\\circ$"},{"key":"C","text":"$62^\\circ$"},{"key":"D","text":"$124^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of angles in a triangle is $180^\\circ$. Therefore, angle $F = 180^\\circ - 53^\\circ - 71^\\circ = 56^\\circ$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FUGB4C', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'What is the value of $x$ in the solution to the system of equations below?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FW2CNT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $2x^2 + 11x + 17 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = 11^2 - 4(2)(17) = 121 - 136 = -15$. Since the discriminant is negative, the equation has no real solutions. The distractor $1$ incorrectly assumes a negative discriminant means exactly one solution, confusing it with the case where the discriminant equals zero. The distractor $2$ assumes all quadratic equations have two real solutions without checking the discriminant. The distractor $4$ misapplies the degree concept or confuses with a higher-degree polynomial.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G5ZUIF', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A parking garage charges a flat fee of 11 dollars plus 3 dollars for each hour a car is parked. If a driver wants to spend no more than 38 dollars, which inequality represents the number of hours $h$ the driver can park?', NULL, $lyceon_json$[{"key":"A","text":"$3h + 11 \\leq 38$"},{"key":"B","text":"$3h + 11 \\geq 38$"},{"key":"C","text":"$11h + 3 \\leq 38$"},{"key":"D","text":"$3h - 11 \\leq 38$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the flat fee of $11$ dollars plus $3$ dollars per hour, giving $3h + 11$. Since the driver wants to spend no more than $38$ dollars, the correct inequality is $3h + 11 \\leq 38$. Using $\\geq$ reverses the constraint and would mean spending at least $38$ dollars. Writing $11h + 3$ swaps the per-hour rate and the flat fee. Subtracting $11$ instead of adding it misrepresents the flat fee as a discount.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G8VZQB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed at the first intersection measures $118^\\circ$. What is the measure of the co-interior angle at the second intersection on the same side of the transversal?', NULL, $lyceon_json$[{"key":"A","text":"$52^\\circ$"},{"key":"B","text":"$62^\\circ$"},{"key":"C","text":"$118^\\circ$"},{"key":"D","text":"$128^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'Co-interior angles (also called same-side interior or consecutive interior angles) formed by parallel lines and a transversal are supplementary, meaning they sum to $180^\\circ$. The co-interior angle is $180^\\circ - 118^\\circ = 62^\\circ$. The value $52^\\circ$ results from an arithmetic slip in the subtraction. Selecting $118^\\circ$ reflects the misconception that co-interior angles are equal, confusing them with corresponding or alternate interior angles. The value $128^\\circ$ arises from an incorrect setup such as adding $10^\\circ$ to $118^\\circ$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GGJTBB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a survey of 200 commuters, 74 take the bus, 53 take the train, and 23 take both the bus and the train. The remaining commuters use neither. If a commuter is selected at random from those who take the bus or the train (or both), what is the probability that the commuter takes only the train?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{30}{104}$"},{"key":"B","text":"$\\frac{53}{104}$"},{"key":"C","text":"$\\frac{30}{200}$"},{"key":"D","text":"$\\frac{51}{104}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By inclusion-exclusion, the number who take bus or train (or both) is $74 + 53 - 23 = 104$. Those who take only the train are $53 - 23 = 30$. The probability is $\\frac{30}{104}$, which simplifies to $\\frac{15}{52}$. The answer $\\frac{53}{104}$ fails to subtract the 23 commuters who take both from the train total. The answer $\\frac{30}{200}$ uses the full survey population as the denominator instead of conditioning on those who take bus or train. The answer $\\frac{51}{104}$ results from incorrectly subtracting only the bus-only commuters from 104.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J1N7TK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A researcher collects data on the age (in years) and resale value (in dollars) of 15 used cars of the same model. The scatterplot of the data shows a strong negative linear association. Which of the following best describes the relationship?', NULL, $lyceon_json$[{"key":"A","text":"As the age of the car increases, the resale value tends to increase."},{"key":"B","text":"As the age of the car increases, the resale value tends to decrease."},{"key":"C","text":"There is no consistent pattern between the age and resale value of the cars."},{"key":"D","text":"The resale value of the cars remains constant regardless of age."}]$lyceon_json$::jsonb, 'B', NULL, E'A strong negative linear association means that as one variable increases, the other tends to decrease. Therefore, as the age of the car increases, the resale value tends to decrease.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JFTUTY', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $7x + 3y = 39$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 13)$"},{"key":"B","text":"$(0, 39)$"},{"key":"C","text":"$(13, 0)$"},{"key":"D","text":"$(0, 7)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $y$-intercept is the point where $x = 0$. Substituting $x = 0$ into $7(0) + 3y = 39$ gives $3y = 39$, so $y = 13$. The $y$-intercept is $(0, 13)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JJZGLA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set has $9$ values with a mean of $43$. If a tenth value of $97$ is added to the data set, what is the mean of the new data set?', NULL, $lyceon_json$[{"key":"A","text":"$48.4$"},{"key":"B","text":"$46.7$"},{"key":"C","text":"$70.0$"},{"key":"D","text":"$53.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the original $9$ values is $9 \\times 43 = 387$. Adding $97$ gives a new sum of $387 + 97 = 484$. The new mean is $\\frac{484}{10} = 48.4$. The value $70.0$ comes from averaging only $43$ and $97$, treating them as two data points rather than using the full data set. The value $53.5$ comes from an error in computing the original sum. The value $46.7$ results from an arithmetic slip in the division.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KXC8SI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'Two independent random samples are taken from the same population. Sample A has 400 respondents and finds that $62\\%$ support a proposal, with a margin of error of $\\pm 4.8\\%$. Sample B has 1,600 respondents and finds that $59\\%$ support the proposal, with a margin of error of $\\pm 2.4\\%$. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The confidence intervals from the two samples overlap, so the results are consistent with each other."},{"key":"B","text":"Sample A is more reliable because it found a higher level of support."},{"key":"C","text":"The true population proportion must be exactly $59\\%$ because Sample B is larger."},{"key":"D","text":"The two samples contradict each other because they produced different percentages."}]$lyceon_json$::jsonb, 'A', NULL, E'Sample A''s confidence interval is $62\\% \\pm 4.8\\%$, or $57.2\\%$ to $66.8\\%$. Sample B''s confidence interval is $59\\% \\pm 2.4\\%$, or $56.6\\%$ to $61.4\\%$. These intervals overlap (from about $57.2\\%$ to $61.4\\%$), so the two results are consistent. The claim that Sample A is more reliable because it found higher support confuses a higher estimate with reliability; larger samples produce narrower margins of error. Stating the true proportion must be exactly $59\\%$ treats the sample result as the exact population value. Calling the results contradictory ignores the overlapping confidence intervals.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L5Q3KG', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $h$ is defined such that $h(2) = 11$ and $h$ has a rate of change of $-\\frac{7}{3}$. For which value of $x$ does $h(x) = h(x + 6) + 14$?', NULL, $lyceon_json$[{"key":"A","text":"All values of $x$"},{"key":"B","text":"$x = 2$ only"},{"key":"C","text":"$x = 5$ only"},{"key":"D","text":"There is no such value of $x$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that the equation holds for all values of $x$. Since $h$ is linear with slope $-\\frac{7}{3}$, we can write $h(x) = -\\frac{7}{3}x + b$ for some constant $b$. Then $h(x + 6) = -\\frac{7}{3}(x + 6) + b = -\\frac{7}{3}x - 14 + b$. So $h(x + 6) + 14 = -\\frac{7}{3}x - 14 + b + 14 = -\\frac{7}{3}x + b = h(x)$. The equation simplifies to an identity, meaning it holds for every real number $x$. Choosing $x = 2$ only reflects a misunderstanding where one plugs in a specific point rather than recognizing the identity. Choosing $x = 5$ comes from incorrectly setting up and solving an equation. Claiming no solution exists reflects a misunderstanding of how linear functions behave under translation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MB76ZK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'After a $15\\%$ discount, a customer pays $391$ dollars for a television. The store then charges a flat $8\\%$ sales tax on the discounted price. What is the total amount the customer pays, including tax, in dollars? (Round to the nearest cent.)', NULL, $lyceon_json$[{"key":"A","text":"399.28 dollars"},{"key":"B","text":"422.28 dollars"},{"key":"C","text":"460.00 dollars"},{"key":"D","text":"449.65 dollars"}]$lyceon_json$::jsonb, 'B', NULL, E'The discounted price is 391 dollars. The sales tax is $8\\%$ of 391, which is $0.08 \\times 391 = 31.28$ dollars. The total amount is $391 + 31.28 = 422.28$ dollars. The distractor 460.00 dollars incorrectly recovers the original price before discount ($391 \\div 0.85 = 460$) and treats that as the total. The distractor 399.28 dollars adds a flat 8.28 instead of computing $8\\%$ of the discounted price. The distractor 449.65 dollars results from applying the tax rate to the original price rather than the discounted price.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MCSRLT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands at point $A$ and measures the angle of elevation to the top of a building to be $34^\\circ$. The surveyor then walks $50$ feet directly toward the building to point $C$ and measures the angle of elevation to be $59^\\circ$. Which of the following expressions gives the height, in feet, of the building?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{50 \\sin(34^\\circ) \\sin(59^\\circ)}{\\sin(25^\\circ)}$"},{"key":"B","text":"$\\frac{50 \\tan(34^\\circ) \\tan(59^\\circ)}{\\tan(59^\\circ) - \\tan(34^\\circ)}$"},{"key":"C","text":"$\\frac{50}{\\tan(59^\\circ) - \\tan(34^\\circ)}$"},{"key":"D","text":"$50(\\tan(34^\\circ) + \\tan(59^\\circ))$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $h$ be the height and $d$ the horizontal distance from point $C$ to the base. Then $\\tan(59^\\circ) = \\frac{h}{d}$ and $\\tan(34^\\circ) = \\frac{h}{d + 50}$. Solving for $d$ gives $d = \\frac{h}{\\tan(59^\\circ)}$ and $d + 50 = \\frac{h}{\\tan(34^\\circ)}$. Subtracting yields $50 = h\\left(\\frac{1}{\\tan(34^\\circ)} - \\frac{1}{\\tan(59^\\circ)}\\right) = h \\cdot \\frac{\\tan(59^\\circ) - \\tan(34^\\circ)}{\\tan(34^\\circ)\\tan(59^\\circ)}$, so $h = \\frac{50\\tan(34^\\circ)\\tan(59^\\circ)}{\\tan(59^\\circ) - \\tan(34^\\circ)}$. The sine-based expression applies law of sines to an incorrectly constructed triangle. The expression $\\frac{50}{\\tan(59^\\circ) - \\tan(34^\\circ)}$ omits the product of tangents in the numerator. The sum-of-tangents expression incorrectly adds rather than combining the tangent equations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MO38IP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A nutritionist observes that among 130 adults who voluntarily switched to a high-fiber diet, the average cholesterol level decreased over six months. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"There is an association between switching to a high-fiber diet and decreased cholesterol among the adults in the study."},{"key":"B","text":"A high-fiber diet causes cholesterol to decrease in all adults."},{"key":"C","text":"The high-fiber diet is more effective than medication at lowering cholesterol."},{"key":"D","text":"Any adult who switches to a high-fiber diet will experience a decrease in cholesterol."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the adults voluntarily chose to switch diets, this is an observational study, not a randomized experiment. Observational studies can identify associations but cannot establish causation. The correct conclusion states an association between the diet switch and cholesterol decrease among the participants. Claiming the diet causes cholesterol to decrease goes beyond what an observational study can support. Comparing the diet to medication introduces a comparison not present in the study. Generalizing the result to any adult ignores that the participants were self-selected and may differ from the broader population.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N9TUMU', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{11x - 5}{(x - 3)(x + 2)} = \\frac{A}{x - 3} + \\frac{B}{x + 2}$, what is the value of $A + B$?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$7$"},{"key":"C","text":"$5$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using partial fraction decomposition: $11x - 5 = A(x + 2) + B(x - 3)$. Expanding gives $(A + B)x + (2A - 3B) = 11x - 5$. Comparing coefficients of $x$: $A + B = 11$. No further computation is needed. Alternatively, setting $x = 3$ gives $28 = 5A$ so $A = \\frac{28}{5}$, and setting $x = -2$ gives $-27 = -5B$ so $B = \\frac{27}{5}$, confirming $A + B = \\frac{55}{5} = 11$. The distractor $7$ results from a sign error when setting up $2A - 3B = -5$ and solving incorrectly. The distractor $5$ comes from confusing the constant $-5$ with the answer. The distractor $16$ arises from incorrectly adding $11 + 5$ instead of using the coefficient comparison.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OMO9XQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $7$ and $9$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{32}$"},{"key":"B","text":"$\\sqrt{130}$"},{"key":"C","text":"$16$"},{"key":"D","text":"$\\sqrt{144}$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, $c^2 = 7^2 + 9^2 = 49 + 81 = 130$, so $c = \\sqrt{130}$. The value $\\sqrt{32}$ results from subtracting the squares ($81 - 49 = 32$) instead of adding them. The value $16$ comes from adding the legs directly ($7 + 9$), confusing a sum of sides with the Pythagorean relationship. The value $\\sqrt{144} = 12$ results from a computational error in adding $49 + 81$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OSVF8Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a scatterplot of data is given by $y = 1.7x + 23$, where $x$ represents the number of months since January 2020 and $y$ represents the monthly revenue, in thousands of dollars, of a small business. What does the slope $1.7$ represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The predicted revenue increases by $1{,}700$ dollars for each additional month."},{"key":"B","text":"The predicted revenue in January 2020 was $1{,}700$ dollars."},{"key":"C","text":"The predicted revenue increases by $1.7\\%$ each month."},{"key":"D","text":"The predicted total revenue after $1.7$ months is $23{,}000$ dollars."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $1.7$ means that for each additional month, the predicted revenue increases by $1.7$ thousand dollars, which is $1{,}700$ dollars. The value $23$ (the y-intercept) represents the predicted revenue in January 2020, not the slope. Interpreting $1.7$ as a percentage increase confuses a linear model with an exponential one. The claim about total revenue after $1.7$ months misinterprets both the slope and the y-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OW2YO0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the age (in years) and resting heart rate (in beats per minute) of $40$ adults. The line of best fit is $\\hat{y} = -0.4x + 94$, and one data point is $(55, 78)$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$72$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value at $x = 55$ is $\\hat{y} = -0.4(55) + 94 = -22 + 94 = 72$. The residual is the actual value minus the predicted value: $78 - 72 = 6$. The value $-6$ reverses the subtraction order (predicted minus actual). The value $72$ is the predicted value itself, not the residual. The value $16$ results from an error in computing the predicted value, such as using $-0.4(55) + 94 = 62$ and then computing $78 - 62$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P5JMP3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 150 residents in a city found that 57 prefer public parks over private gyms for exercise. The margin of error for this estimate is $\\pm 7\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"It is plausible that between $31\\%$ and $45\\%$ of all residents in the city prefer public parks."},{"key":"B","text":"Exactly $38\\%$ of all residents in the city prefer public parks."},{"key":"C","text":"Between $31\\%$ and $45\\%$ of the sampled residents prefer public parks."},{"key":"D","text":"If another sample is taken, exactly $38\\%$ will prefer public parks."}]$lyceon_json$::jsonb, 'A', NULL, E'The sample proportion is $\\frac{57}{150} = 38\\%$. With a margin of error of $\\pm 7\\%$, the plausible range for the population proportion is $38\\% - 7\\% = 31\\%$ to $38\\% + 7\\% = 45\\%$. The statement that exactly $38\\%$ of all residents prefer public parks treats the sample statistic as the exact population parameter, ignoring sampling variability. The claim about the sampled residents confuses the population inference with the sample itself. The prediction that another sample will yield exactly $38\\%$ misunderstands that sample results vary.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PEQ10F', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'A plumber charges a flat fee of $47 for a service call plus $31 per hour of labor. An electrician charges a flat fee of $83 but only $19 per hour. For how many hours of work would both professionals charge the same total amount?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Setting the two cost expressions equal: $47 + 31h = 83 + 19h$. Subtracting $19h$ from both sides gives $47 + 12h = 83$. Subtracting $47$ from both sides yields $12h = 36$, so $h = 3$. Both professionals charge $47 + 31(3) = 140$ dollars and $83 + 19(3) = 140$ dollars respectively, confirming $h = 3$ is correct.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PI48EC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid is formed by placing a hemisphere on top of a cylinder. The hemisphere and cylinder share the same radius of $5$ centimeters. The total height of the solid, measured from the base of the cylinder to the top of the hemisphere, is $19$ centimeters. What is the volume of the solid, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$350\\pi + \\frac{250\\pi}{3}$"},{"key":"B","text":"$475\\pi$"},{"key":"C","text":"$350\\pi$"},{"key":"D","text":"$350\\pi + \\frac{500\\pi}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The hemisphere has radius $5$, so its height is $5$ cm. The cylinder height is $19 - 5 = 14$ cm. The cylinder volume is $\\pi(5^2)(14) = 350\\pi$. The hemisphere volume is $\\frac{1}{2} \\cdot \\frac{4}{3}\\pi(5^3) = \\frac{250\\pi}{3}$. The total volume is $350\\pi + \\frac{250\\pi}{3}$. The value $475\\pi$ results from using the full height $19$ for the cylinder ($\\pi(25)(19) = 475\\pi$) without accounting for the hemisphere occupying the top $5$ cm. The value $350\\pi$ counts only the cylinder volume, omitting the hemisphere entirely. The value $350\\pi + \\frac{500\\pi}{3}$ uses the full sphere volume instead of half.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R2VWJ2', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A linear function $g$ satisfies $g(3) = 17$ and $g(11) = 53$. What is the value of $g(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3.5', ARRAY['7/2', '3.5'], E'First, find the slope: $m = \\frac{53 - 17}{11 - 3} = \\frac{36}{8} = \\frac{9}{2}$. Using point-slope form with $(3, 17)$: $g(x) - 17 = \\frac{9}{2}(x - 3)$, so $g(x) = \\frac{9}{2}x - \\frac{27}{2} + 17 = \\frac{9}{2}x - \\frac{27}{2} + \\frac{34}{2} = \\frac{9}{2}x + \\frac{7}{2}$. Therefore $g(0) = \\frac{7}{2} = 3.5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TMZLQF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $17$ feet and a width of $11$ feet. What is the area, in square feet, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"$56$"},{"key":"B","text":"$170$"},{"key":"C","text":"$187$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is length times width: $17 \\times 11 = 187$ square feet. The value $56$ is the perimeter ($2(17 + 11) = 56$), not the area. The value $170$ results from an arithmetic slip such as computing $17 \\times 10$ instead of $17 \\times 11$. The value $28$ comes from adding the two dimensions ($17 + 11 = 28$) instead of multiplying them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TYY4DH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = -2(x - 5)^2 + 18$. What is the maximum value of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$5$"},{"key":"C","text":"$18$"},{"key":"D","text":"$68$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function is in vertex form $h(x) = a(x - p)^2 + k$ with $a = -2$, vertex at $(5, 18)$. Since $a < 0$, the parabola opens downward, and the vertex represents the maximum. The maximum value is $18$. The distractor $-2$ confuses the leading coefficient with the maximum value. The distractor $5$ confuses the $x$-coordinate of the vertex with the maximum output of the function. The distractor $68$ results from incorrectly computing $2(25) + 18 = 68$, treating the leading coefficient as positive and evaluating at a wrong point.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UMOOVK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A trapezoidal plot of land has parallel sides of length $23$ meters and $17$ meters. The perpendicular distance between the parallel sides is $14$ meters. What is the area, in square meters, of the plot?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '280', ARRAY['280'], E'The area of a trapezoid is $A = \\frac{1}{2}(b_1 + b_2) \\times h$, where $b_1$ and $b_2$ are the parallel sides and $h$ is the perpendicular distance between them. Substituting gives $A = \\frac{1}{2}(23 + 17)(14) = \\frac{1}{2}(40)(14) = 280$ square meters. A common error is omitting the factor of $\\frac{1}{2}$, which gives $560$. Another error is multiplying only one base by the height, yielding either $23 \\times 14 = 322$ or $17 \\times 14 = 238$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UWB0I3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A researcher randomly assigns 86 participants to either a standing-desk group or a traditional-desk group for 10 weeks and measures their reported back pain levels. The standing-desk group reports significantly less back pain on average. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The use of standing desks likely caused the reduction in reported back pain among the participants."},{"key":"B","text":"Standing desks reduce back pain for all office workers."},{"key":"C","text":"There is an association, but not necessarily a causal relationship, between standing desks and back pain."},{"key":"D","text":"The result is invalid because 86 participants is too small a sample."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the researcher randomly assigned participants to groups, this is a randomized controlled experiment. Random assignment allows causal conclusions about the treatment''s effect on the participants. The conclusion that standing desks caused the reduction in reported back pain is appropriate for the study''s participants. Generalizing to all office workers goes beyond the study''s scope, since the participants may not represent all office workers. Limiting the conclusion to association only would be correct for an observational study, but underestimates the strength of evidence from a randomized experiment. Dismissing the result due to sample size alone is not justified without further statistical analysis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VIAF4J', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A box contains 9 tiles: 4 are red and numbered 1 through 4, and 5 are blue and numbered 1 through 5. One tile is drawn at random. Given that the tile drawn is numbered 3 or higher, what is the probability that it is red?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2}{5}$"},{"key":"B","text":"$\\frac{2}{9}$"},{"key":"C","text":"$\\frac{4}{9}$"},{"key":"D","text":"$\\frac{3}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Tiles numbered 3 or higher: red tiles 3, 4 (2 tiles) and blue tiles 3, 4, 5 (3 tiles), for a total of 5 tiles. The conditional probability of drawing a red tile given the number is 3 or higher is $\\frac{2}{5}$. The answer $\\frac{2}{9}$ incorrectly uses the total 9 tiles as the denominator instead of conditioning on the event. The answer $\\frac{4}{9}$ uses the total count of red tiles over all tiles, ignoring the condition. The answer $\\frac{3}{5}$ confuses the count of blue qualifying tiles for red.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VRJDJH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A printer produces pages at a rate of $37$ pages per minute. If the printer operates for $2$ hours and $13$ minutes, which of the following is closest to the total number of pages produced?', NULL, $lyceon_json$[{"key":"A","text":"$4,921$"},{"key":"B","text":"$4,810$"},{"key":"C","text":"$4,440$"},{"key":"D","text":"$5,291$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, convert $2$ hours and $13$ minutes to minutes: $2 \\times 60 + 13 = 133$ minutes. Then multiply by the rate: $37 \\times 133 = 4{,}921$ pages. The answer $4{,}440$ comes from using only $120$ minutes (ignoring the $13$ extra minutes). The answer $5{,}291$ comes from incorrectly computing $37 \\times 143$, adding $23$ minutes instead of $13$. The answer $4{,}810$ comes from an arithmetic slip in the multiplication.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
