INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X6UA61', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In a right triangle, one of the acute angles measures $30^\\circ$ and the hypotenuse has length $23$. What is the length of the side opposite the $30^\\circ$ angle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11.5', ARRAY['23/2', '11.5'], E'In a right triangle with a $30^\\circ$ angle, the side opposite the $30^\\circ$ angle is half the hypotenuse. Therefore the opposite side is $\\frac{23}{2} = 11.5$. Equivalently, $\\sin(30^\\circ) = \\frac{\\text{opposite}}{23}$, so the opposite side is $23 \\times \\sin(30^\\circ) = 23 \\times 0.5 = 11.5$. A common error is using cosine instead of sine, which would yield $23 \\cos(30^\\circ) \\approx 19.9$, the length of the adjacent side rather than the opposite side.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XC8FWY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution to the equation $x^2 + 7x - 44 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Factoring: $x^2 + 7x - 44 = (x + 11)(x - 4) = 0$, giving $x = -11$ or $x = 4$. The positive solution is $4$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y18HCP', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $5x - 13y = 26$. Line $q$ is perpendicular to line $p$ and passes through the point $(-1, 7)$. What is the $x$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{22}{13}$"},{"key":"B","text":"$\\frac{104}{13}$"},{"key":"C","text":"$\\frac{78}{5}$"},{"key":"D","text":"$-\\frac{22}{13}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{22}{13}$. First, rewrite line $p$ in slope-intercept form: $y = \\frac{5}{13}x - 2$, so the slope of $p$ is $\\frac{5}{13}$. The perpendicular slope is $-\\frac{13}{5}$. Using point-slope form with $(-1, 7)$: $y - 7 = -\\frac{13}{5}(x + 1)$. To find the $x$-intercept, set $y = 0$: $-7 = -\\frac{13}{5}(x + 1)$, so $\\frac{35}{13} = x + 1$, giving $x = \\frac{35}{13} - 1 = \\frac{22}{13}$. The value $\\frac{104}{13}$ results from incorrectly using the original slope rather than the perpendicular slope. The value $\\frac{78}{5}$ comes from confusing the roles of the perpendicular and original slopes and finding the $y$-intercept instead. The value $-\\frac{22}{13}$ introduces a sign error in the final subtraction step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YJPO5L', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $7x^3 - 21x^2 + 14x$?', NULL, $lyceon_json$[{"key":"A","text":"$7x(x^2 - 3x + 2)$"},{"key":"B","text":"$7x(x^2 - 3x - 2)$"},{"key":"C","text":"$7(x^3 - 3x + 2)$"},{"key":"D","text":"$x(7x^2 - 21x)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring out the greatest common factor $7x$ from each term gives $7x(x^2 - 3x + 2)$. The distractor $7x(x^2 - 3x - 2)$ results from a sign error on the last term when dividing $14x$ by $7x$. The distractor $7(x^3 - 3x + 2)$ fails to factor out $x$ and incorrectly handles the middle term. The distractor $x(7x^2 - 21x)$ only partially factors, dropping the $+14x$ term entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YLXANM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, point $D$ lies on side $\\overline{BC}$ such that $\\overline{AD}$ bisects angle $A$. If the measure of angle $B$ is $38^\\circ$ and the measure of angle $ADB$ is $107^\\circ$, what is the measure, in degrees, of angle $C$?', NULL, $lyceon_json$[{"key":"A","text":"$35^\\circ$"},{"key":"B","text":"$38^\\circ$"},{"key":"C","text":"$70^\\circ$"},{"key":"D","text":"$72^\\circ$"}]$lyceon_json$::jsonb, 'D', NULL, E'In triangle $ABD$, the angle sum gives angle $BAD = 180^\\circ - 38^\\circ - 107^\\circ = 35^\\circ$. Since $\\overline{AD}$ bisects angle $A$, angle $DAC = 35^\\circ$ as well, so angle $A = 70^\\circ$. In triangle $ABC$, angle $C = 180^\\circ - 38^\\circ - 70^\\circ = 72^\\circ$. The value $35^\\circ$ is only half of angle $A$ and represents stopping at the bisected angle rather than finding angle $C$. The value $38^\\circ$ results from confusing angle $C$ with the given angle $B$. The value $70^\\circ$ is the full measure of angle $A$, not angle $C$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z8VBQ6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = \\frac{4x^2 - 9}{2x + 3}$ for $x \\neq -\\frac{3}{2}$. Which of the following describes the end behavior of $f$ as $x$ increases without bound?', NULL, $lyceon_json$[{"key":"A","text":"$f(x)$ approaches $2$"},{"key":"B","text":"$f(x)$ increases without bound"},{"key":"C","text":"$f(x)$ approaches $-\\frac{3}{2}$"},{"key":"D","text":"$f(x)$ approaches $0$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factoring the numerator: $4x^2 - 9 = (2x + 3)(2x - 3)$. For $x \\neq -\\frac{3}{2}$, $f(x) = \\frac{(2x + 3)(2x - 3)}{2x + 3} = 2x - 3$. This simplifies to a linear function with positive slope, so as $x$ increases without bound, $f(x)$ also increases without bound. The distractor stating $f(x)$ approaches $2$ results from treating the leading coefficient of $2x - 3$ as a horizontal asymptote. The distractor $-\\frac{3}{2}$ confuses the excluded domain value with the end behavior. The distractor stating $f(x)$ approaches $0$ incorrectly applies the rule for rational functions whose denominator degree exceeds the numerator degree.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZQU200', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{3(2x - 7)}{4} + 11 = 5x - 2$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{23}{14}$"},{"key":"B","text":"$\\frac{31}{14}$"},{"key":"C","text":"$3$"},{"key":"D","text":"$\\frac{65}{14}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $\\frac{31}{14}$. Multiply both sides by $4$ to clear the fraction: $3(2x - 7) + 44 = 20x - 8$. Distributing gives $6x - 21 + 44 = 20x - 8$, which simplifies to $6x + 23 = 20x - 8$. Subtracting $6x$ and adding $8$ to both sides yields $31 = 14x$, so $x = \\frac{31}{14}$. The value $\\frac{23}{14}$ results from a sign error when moving the constant terms. The value $3$ comes from incorrectly simplifying the fractional expression without properly multiplying through by $4$. The value $\\frac{65}{14}$ arises from setting up the equation incorrectly after clearing the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW201N8AT', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the museum''s board of directors initially resisted the proposal, the curator argued that displaying the Benin Bronzes alongside contemporary Nigerian sculptures would allow visitors to appreciate not only the technical mastery of sixteenth-century Edo metalworkers _______ the enduring influence of those traditions on modern West African art.', $lyceon_json$[{"key":"A","text":"and also"},{"key":"B","text":"but also"},{"key":"C","text":"but"},{"key":"D","text":"and"}]$lyceon_json$::jsonb, 'B', NULL, E'The correlative conjunction pair "not only...but also" is the standard construction in English. The sentence uses "not only" before "the technical mastery of sixteenth-century Edo metalworkers," so the second element must be introduced by "but also" to complete the parallel correlative pair. "And also" breaks the correlative pattern because "not only" pairs exclusively with "but also," not with "and also." Using "but" alone omits "also" and weakens the parallel emphasis that the correlative construction is designed to create. Using "and" alone ignores the "not only" that opened the construction and fails to complete the required correlative pair.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20KORR2', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The fruit fly Drosophila melanogaster has been a staple of genetics laboratories since Thomas Hunt Morgan''s experiments in 1910. Its genome contains approximately 13,600 genes distributed across just four pairs of chromosomes. <u>A single female can produce up to five hundred eggs in ten days, and the entire life cycle from egg to adult takes only about twelve days under standard conditions.</u> These characteristics make Drosophila an exceptionally practical organism for studying inheritance patterns across multiple generations in a compressed timeframe.', $lyceon_json$[{"key":"A","text":"It provides specific details that help explain why Drosophila is well suited for genetic research."},{"key":"B","text":"It challenges a widely held assumption about the reproductive habits of laboratory organisms."},{"key":"C","text":"It introduces a new line of inquiry that the rest of the passage will explore in depth."},{"key":"D","text":"It contrasts the reproductive capacity of Drosophila with that of other commonly studied species."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the underlined sentence provides specific details explaining why Drosophila is well suited for genetic research. The underlined sentence gives concrete reproductive data — five hundred eggs in ten days, twelve-day life cycle — and the following sentence explicitly connects these traits to the organism''s practicality for multi-generation studies. The choice about challenging an assumption is wrong because the passage presents these facts straightforwardly, not as a counterargument. The choice about introducing a new line of inquiry misidentifies the sentence''s role; the passage does not shift to a new topic afterward. The choice about contrasting Drosophila with other species is wrong because no other species is mentioned.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22MZM66', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Each of the seventeen granite obelisks erected along the ancient trade route between Aksum and Adulis _______ a distinct set of carvings that historians believe represents a different royal lineage.', $lyceon_json$[{"key":"A","text":"feature"},{"key":"B","text":"features"},{"key":"C","text":"are featuring"},{"key":"D","text":"have featured"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the verb is "Each," which is a singular indefinite pronoun. The prepositional phrase "of the seventeen granite obelisks erected along the ancient trade route between Aksum and Adulis" modifies "Each" but does not change the number of the subject. Therefore, the verb must be singular: "features." The plural form "feature" incorrectly treats "obelisks" as the subject. "Are featuring" uses the progressive aspect, which is inappropriate because the carvings are a permanent characteristic, not an ongoing action. "Have featured" incorrectly uses the present perfect plural, which both mismatches the singular subject and implies the carvings are a completed action rather than a permanent attribute.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22Q05WW', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, what can most reasonably be inferred about the relationship between garden management structure and crop productivity?', E'Sociologist Amara Osei studied community gardens in three mid-sized cities in Ghana between 2016 and 2021. She found that gardens managed by rotating volunteer committees experienced a 37 percent decline in crop yields over the five-year period, while gardens managed by a single paid coordinator maintained stable yields. Osei noted that volunteer committees frequently changed planting schedules, adopted inconsistent watering practices, and allowed plots to lie fallow for unpredictable intervals. The gardens with paid coordinators followed standardized planting calendars and enforced regular irrigation schedules.', $lyceon_json$[{"key":"A","text":"Consistent management practices, such as those enforced by paid coordinators, contribute to maintaining stable crop yields over time."},{"key":"B","text":"Volunteer-managed gardens produced lower-quality crops than coordinator-managed gardens, even when total yields were similar."},{"key":"C","text":"Paid coordinators were more knowledgeable about horticulture than the volunteers who served on rotating committees."},{"key":"D","text":"Community gardens in Ghana are less productive than commercial farms in the same regions."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that consistent management practices contribute to stable crop yields. The passage links the coordinators'' standardized calendars and regular irrigation to stable yields, while inconsistent volunteer practices coincided with declining yields. The choice about crop quality addresses an outcome the passage never measures. The choice about coordinators being more knowledgeable assumes a cause the passage does not establish; it attributes the difference to practices, not individual expertise. The choice comparing community gardens to commercial farms goes entirely beyond the text, which makes no such comparison.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25IYHVZ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ethnoarchaeologist Priya Subramaniam has argued that the ceramic glazing techniques found at the Harappan site near Dholavira—techniques once attributed to later Mauryan _______ were in fact developed independently by artisans who predated the Mauryan dynasty by at least four centuries.', $lyceon_json$[{"key":"A","text":"craftspeople,"},{"key":"B","text":"craftspeople—"},{"key":"C","text":"craftspeople;"},{"key":"D","text":"craftspeople"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice closes the parenthetical interruption with an em dash, matching the opening em dash after "Dholavira." The phrase "techniques once attributed to later Mauryan craftspeople" is an appositive aside set off by paired em dashes. The closing dash must match the opening one to properly bracket the interruption, after which the main clause resumes with "were in fact developed independently." A comma would fail to close the dash-bounded parenthetical and would create a structural mismatch. A semicolon would incorrectly treat what follows as a new independent clause, but "were in fact developed independently" lacks its own subject and depends on the main clause''s subject. Omitting punctuation entirely leaves the parenthetical unclosed, producing a grammatically incoherent sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27125SA', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing a research summary for a neuroscience seminar, a student wants to present the study''s findings while acknowledging a limitation that qualifies the conclusions. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29XJ7SX', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Svalbard Global Seed Vault, carved into a mountainside on a Norwegian _______ houses over 1.3 million seed samples from nearly every country, safeguarding agricultural biodiversity against catastrophic crop failures.', $lyceon_json$[{"key":"A","text":"archipelago"},{"key":"B","text":"archipelago;"},{"key":"C","text":"archipelago,"},{"key":"D","text":"archipelago—and"}]$lyceon_json$::jsonb, 'C', NULL, E'A comma is needed after "archipelago" to close the participial phrase "carved into a mountainside on a Norwegian archipelago," which is a nonrestrictive modifier set off by the comma after "Vault." The main clause is "The Svalbard Global Seed Vault...houses over 1.3 million seed samples," with the participial phrase inserted between the subject and verb. A closing comma is required to match the opening comma and return to the main clause. Omitting punctuation entirely fuses the modifier into the verb phrase without proper separation. A semicolon would incorrectly signal that what follows is a new independent clause, but "houses over 1.3 million seed samples" has no subject of its own—it is the predicate of "The Svalbard Global Seed Vault." An em dash followed by "and" introduces an unnecessary conjunction and a structural break that disrupts the simple subject-verb relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AZQDHI', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing a report for a geography class, a student wants to highlight the primary economic benefit of the canal discussed in the notes. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CNKGZS', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken Venkatesh''s argument?', E'Economist Priya Venkatesh argues that cooperative land trusts in rural Karnataka have improved smallholder farmers'' bargaining power with grain wholesalers. Under the trust model, individual farmers pool their harvests into a collective inventory, enabling the trust to negotiate bulk sale prices that exceed what any single farmer could obtain. Venkatesh contends that this collective approach has narrowed the price gap between what wholesalers pay farmers and what consumers ultimately spend.', $lyceon_json$[{"key":"A","text":"Farmers participating in Karnataka land trusts received per-kilogram prices that were, on average, no higher than those received by non-participating farmers in the same districts between 2018 and 2023."},{"key":"B","text":"Cooperative land trusts in Karnataka require annual membership fees that some farmers find burdensome."},{"key":"C","text":"Grain wholesalers in Karnataka have expanded their operations into neighboring states over the past five years."},{"key":"D","text":"Smallholder farmers in other Indian states have adopted different cooperative models, such as producer companies."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that trust-participating farmers receiving no higher prices than non-participants would directly undermine Venkatesh''s claim that the cooperative model improves bargaining power. The finding about membership fees being burdensome addresses costs of participation but does not challenge whether the trusts actually raise prices. Wholesalers expanding into neighboring states is irrelevant to whether Karnataka trusts improve farmer bargaining outcomes. Other states adopting different cooperative models does not bear on the effectiveness of the specific Karnataka trust model Venkatesh describes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D0MIZG', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Keiko Tanizawa has spent over seventeen years studying the bioluminescent patterns of comb jellies in the Mariana _______ findings have reshaped how scientists understand light production in deep-sea organisms.', $lyceon_json$[{"key":"A","text":"Trench, her"},{"key":"B","text":"Trench her"},{"key":"C","text":"Trench. Her"},{"key":"D","text":"Trench; and her"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage contains two independent clauses: one ending with "Mariana Trench" and one beginning with "her findings." A comma alone between independent clauses creates a comma splice, making "Trench, her" incorrect. Omitting all punctuation creates a run-on sentence, making "Trench her" incorrect. A semicolon followed by "and" is non-standard because a semicolon already signals the boundary between independent clauses, making the coordinating conjunction redundant. A period correctly separates the two independent clauses into distinct sentences.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D88LW7', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the central idea of the text?', E'In the 1870s, the Japanese government dispatched groups of agricultural specialists to study European dairy farming techniques, hoping to introduce milk production to a population that had historically consumed little dairy. These specialists returned with Holstein cattle, pasteurization equipment, and detailed husbandry manuals. Yet adoption remained limited for decades: most Japanese consumers found milk''s taste unfamiliar and unappealing, and Buddhist dietary traditions in many regions discouraged animal-derived foods. It was not until the post-1945 period, when American occupation authorities incorporated powdered milk into school lunch programs, that dairy consumption became widespread in Japan.', $lyceon_json$[{"key":"A","text":"Japan's adoption of dairy consumption was delayed not by a lack of government effort or technical knowledge, but by cultural and religious resistance that only shifted under postwar circumstances."},{"key":"B","text":"The Japanese government's decision to import Holstein cattle in the 1870s was a failure because the cattle could not adapt to Japan's climate."},{"key":"C","text":"Buddhist dietary restrictions have consistently prevented the Japanese population from consuming any animal-derived products throughout history."},{"key":"D","text":"American occupation authorities forced Japan to abandon its traditional dietary practices entirely after 1945."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that Japan''s dairy adoption was delayed by cultural and religious resistance rather than by a lack of government initiative, and that conditions changed only after 1945. The passage traces a clear arc: government efforts in the 1870s, persistent consumer reluctance rooted in taste and Buddhist traditions, and eventual adoption through postwar school lunch programs. The choice about Holstein cattle failing to adapt fabricates a detail absent from the passage. The choice about Buddhist restrictions consistently preventing all animal-product consumption overstates what the passage says, which is that traditions in many regions discouraged such foods. The choice about American authorities forcing Japan to abandon traditional diets entirely exaggerates the passage''s account of powdered milk in school lunches.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E5EHAP', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Although the poet Vashti Osei-Mensah drew extensively from West African oral traditions in her verse, critics who described her work as merely ______ overlooked her radical formal innovations. Osei-Mensah fractured conventional meter, embedded call-and-response structures within sonnet forms, and used tonal patterns from Twi to reshape English prosody — transformations that went far beyond simple reproduction of inherited material.', $lyceon_json$[{"key":"A","text":"derivative"},{"key":"B","text":"provocative"},{"key":"C","text":"esoteric"},{"key":"D","text":"pristine"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "derivative." The passage contrasts critics who dismissed Osei-Mensah''s work as something inadequate with the reality of her radical innovations. The word "derivative" — meaning imitative of others'' work rather than original — fits this contrast perfectly, as the passage argues her work went "far beyond simple reproduction." "Provocative" means deliberately challenging or controversial, which does not align with the critics'' dismissive stance about originality. "Esoteric" means understood by only a small, specialized group, which addresses accessibility rather than originality. "Pristine" means in its original, unspoiled condition, which has no meaningful connection to the critical dismissal described in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I5IFDX', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2019 experiment at the Fermi National Accelerator Laboratory, physicists observed that certain muons wobbled at rates inconsistent with predictions from the Standard _______ prompted a worldwide reexamination of the mathematical frameworks underlying particle physics.', $lyceon_json$[{"key":"A","text":"Model; this discrepancy"},{"key":"B","text":"Model this discrepancy"},{"key":"C","text":"Model, this discrepancy"},{"key":"D","text":"Model: this discrepancy"}]$lyceon_json$::jsonb, 'A', NULL, E'A semicolon correctly joins the two independent clauses: "physicists observed that certain muons wobbled at rates inconsistent with predictions from the Standard Model" and "this discrepancy prompted a worldwide reexamination of the mathematical frameworks underlying particle physics." Both are complete sentences with their own subjects and predicates, so a semicolon is the appropriate boundary. Omitting punctuation entirely produces a run-on. A comma before "this discrepancy" creates a comma splice, since both clauses are independent. A colon would be incorrect here because the second clause does not explain, define, or list what precedes it; rather, it describes a consequence, which is a relationship suited to a semicolon.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IFCDS9', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'When the city council proposed replacing the century-old oak trees lining Hargrove Avenue with modern lampposts, residents organized a swift campaign to ______ the plan. Within forty-eight hours, over three thousand signatures appeared on a petition demanding that the trees remain untouched.', $lyceon_json$[{"key":"A","text":"thwart"},{"key":"B","text":"ratify"},{"key":"C","text":"publicize"},{"key":"D","text":"replicate"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "thwart." The passage describes residents organizing a campaign and collecting signatures to stop the council''s plan, so the blank requires a word meaning to prevent or block something. "Ratify" means to formally approve, which is the opposite of what the residents intended. "Publicize" means to make widely known, but the residents'' goal was to stop the plan, not merely spread awareness of it. "Replicate" means to copy or reproduce, which has no logical connection to opposing a proposal.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ILQ4K5', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JNLHNI', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeological surveys of the Faroe Islands have uncovered charred barley grains and sheep bone fragments dating to approximately 300 CE, roughly four centuries before Norse settlers are traditionally believed to have arrived. __________ these findings do not conclusively establish the identity of these earlier inhabitants, they compel historians to reconsider the long-held narrative that the Norse were the archipelago''s first human occupants.', $lyceon_json$[{"key":"A","text":"Granted,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"While"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct transition is "While" because the sentence presents a concessive relationship: it acknowledges a limitation of the findings (they do not conclusively establish identity) before asserting their significance (they compel historians to reconsider the prevailing narrative). "Granted," although it can introduce concessions, would require the sentence to be restructured as two independent clauses; here the blank leads a dependent clause followed by a comma and main clause, which syntactically requires a subordinating conjunction like "While." "Consequently," signals a result, which misrepresents the relationship between the limitation and the significance. "Specifically," implies elaboration or detail rather than the concession the sentence structure demands.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LHRN4B', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Stavanger found that students who took handwritten notes during lectures retained significantly more conceptual information than those who typed their notes on laptops. __________ the researchers recommended that educators encourage pen-and-paper note-taking in classroom settings where deep comprehension is the primary goal.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "Accordingly," because the second sentence presents a recommendation that follows logically from the finding described in the first sentence. The finding that handwritten notes improve retention directly leads to the recommendation to use pen-and-paper note-taking. "Nevertheless," incorrectly signals a concession, implying the recommendation contradicts the finding. "In contrast," wrongly signals opposition between two ideas that are actually aligned. "Meanwhile," suggests unrelated simultaneous events rather than a cause-and-effect relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LROW4A', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Constructed from volcanic basalt and reinforced with coral mortar, the fortified granaries of medieval Kilwa Kisiwani _______ goods arriving from as far as the Song Dynasty ports of Quanzhou, enabling the Swahili city-state to dominate Indian Ocean trade for nearly two centuries.', $lyceon_json$[{"key":"A","text":"storing"},{"key":"B","text":"stored"},{"key":"C","text":"having stored"},{"key":"D","text":"to store"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence requires a finite verb to serve as the main predicate for the subject "the fortified granaries of medieval Kilwa Kisiwani." The participial phrase "Constructed from volcanic basalt and reinforced with coral mortar" is an introductory modifier, so the main clause must contain a conjugated verb. "Stored" is the correct finite past-tense verb that completes the main clause. "Storing" is a present participle, which would leave the sentence without a main verb—creating a fragment with two participial phrases and no predicate. "Having stored" is a perfect participle that would similarly fail to provide a finite verb for the main clause. "To store" is an infinitive that cannot serve as the main predicate of a sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NX64EE', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologist Tara Okonkwo spent seventeen months cataloging bioluminescent organisms in the Mariana Trench. Her findings were ______ : of the 241 species she documented, 83 had never been recorded by any previous expedition, suggesting that deep-ocean biodiversity has been drastically underestimated.', $lyceon_json$[{"key":"A","text":"inconclusive"},{"key":"B","text":"revelatory"},{"key":"C","text":"redundant"},{"key":"D","text":"contentious"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "revelatory." The passage states that 83 of the 241 documented species had never been recorded before, which constitutes a major discovery revealing previously unknown biodiversity. This makes "revelatory" — meaning serving to reveal something surprising or significant — the precise fit. "Inconclusive" means not leading to a firm conclusion, but the passage presents a definitive finding about underestimated biodiversity. "Redundant" means unnecessary or superfluous, which contradicts the novelty of discovering 83 new species. "Contentious" means causing disagreement, but the passage presents the findings as factual discoveries, not as disputed claims.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OU7EEF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Urban planners in Copenhagen attribute the city''s high cycling rate partly to its extensive network of protected bike lanes. Several North American cities have attempted to replicate this infrastructure. __________ these cities have seen modest increases in cycling, the gains have not approached Copenhagen''s levels, suggesting that infrastructure alone cannot account for the cultural and policy factors that sustain high bicycle ridership.', $lyceon_json$[{"key":"A","text":"Although"},{"key":"B","text":"Because"},{"key":"C","text":"Moreover,"},{"key":"D","text":"Regardless,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "Although" because the sentence establishes a concessive relationship: it acknowledges that North American cities have seen some increase in cycling (a partial success) before pivoting to the more important point that the gains remain far below Copenhagen''s levels. This concession-then-counterpoint structure requires a subordinating conjunction that introduces a conceded fact. "Because" incorrectly signals causation, suggesting the modest increases caused the failure to match Copenhagen. "Moreover," implies the sentence adds a parallel supporting point, but the sentence actually introduces a qualifying contrast. "Regardless," implies that whatever precedes it is being dismissed entirely, but the passage does not dismiss the modest gains; it acknowledges them while noting their insufficiency.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q6XYYL', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes the relationship between the arguments presented in Text 1 and Text 2?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R9AN3E', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most effectively address the critics'' objection while supporting Marchetti''s proposal?', E'Neuroscientist Elena Marchetti proposes that the human brain''s default mode network (DMN) does not merely activate during rest, as traditionally assumed, but actively consolidates episodic memories by replaying neural patterns associated with recent experiences. Marchetti points to fMRI studies showing that DMN regions exhibit sequential activation patterns during quiet wakefulness that mirror the temporal order of stimuli presented during a preceding learning task. Critics counter that these activation patterns may reflect spontaneous neural noise rather than purposeful memory consolidation, since similar sequential patterns occasionally appear in subjects who were not exposed to any learning task beforehand.', $lyceon_json$[{"key":"A","text":"Subjects whose DMN replay patterns most closely matched the temporal order of a preceding learning task recalled significantly more items from that task than subjects whose DMN patterns showed no such correspondence."},{"key":"B","text":"DMN activation during rest was stronger in younger adults than in older adults across all experimental conditions."},{"key":"C","text":"Subjects who engaged in a learning task showed elevated overall DMN activity compared to resting subjects, regardless of the sequential structure of that activity."},{"key":"D","text":"The DMN regions identified by Marchetti overlap substantially with regions previously linked to spatial navigation."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that a correlation between DMN replay fidelity and actual recall performance would both support the memory consolidation claim and counter the critics'' noise objection: if the patterns were random noise, their fidelity would not predict recall. Stronger DMN activation in younger adults addresses age differences, not whether replay reflects consolidation or noise. Elevated overall DMN activity without sequential structure does not distinguish purposeful replay from general arousal. Overlap with spatial navigation regions is anatomically interesting but does not resolve whether sequential patterns represent memory consolidation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RIQ913', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing an article about agricultural science, a student wants to emphasize how the technique described in the notes differs from conventional breeding methods. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RXHSWC', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Until the early twentieth century, most European beekeepers used skep hives — dome-shaped baskets woven from straw. Harvesting honey from a skep required destroying the hive structure and often killed the colony inside. In 1852, Reverend Lorenzo Langstroth patented a hive with removable wooden frames that allowed beekeepers to extract honey without dismantling the hive or harming the bees. By 1910, Langstroth-style hives had largely replaced skeps across Western Europe.', $lyceon_json$[{"key":"A","text":"Langstroth's design was adopted widely because it allowed repeated honey harvests from the same colony, reducing the cost and labor of maintaining apiaries."},{"key":"B","text":"Langstroth's patent was challenged by several European inventors who had independently developed identical hive designs before 1852."},{"key":"C","text":"Skep hives produced higher-quality honey than Langstroth hives because the straw material imparted a distinctive flavor."},{"key":"D","text":"European governments banned the use of skep hives in 1910 due to concerns about bee population declines."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that Langstroth''s design was adopted because it permitted repeated harvests from the same colony, reducing costs. The passage establishes that skeps required destroying the hive, while Langstroth frames allowed extraction without harm — the practical advantage logically explains adoption. The choice about European inventors challenging Langstroth''s patent introduces unsubstantiated claims. The choice about skep hives producing higher-quality honey contradicts the passage''s account of skeps being replaced. The choice about a government ban fabricates a regulatory action the passage does not mention.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SN7C8R', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Zurich recently investigated the role of mycelial networks in distributing phosphorus among trees in temperate forests. By tagging phosphorus isotopes and tracking their movement through soil samples over a fourteen-month period, the team demonstrated that mycorrhizal fungi transferred measurable quantities of phosphorus from nutrient-rich zones to nutrient-depleted zones, effectively subsidizing trees growing in poor soils. The researchers concluded that these fungal networks function as redistribution systems that reduce nutrient inequality among neighboring trees.', $lyceon_json$[{"key":"A","text":"Mycorrhizal fungi redistribute phosphorus through underground networks, reducing nutrient disparities among trees in temperate forests."},{"key":"B","text":"The University of Zurich conducted the first study ever to use isotope tagging for tracking soil nutrients."},{"key":"C","text":"Trees in nutrient-depleted soils grow more slowly than those in nutrient-rich zones regardless of fungal activity."},{"key":"D","text":"Phosphorus is the most critical nutrient for tree growth in temperate forest ecosystems."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that mycorrhizal fungi redistribute phosphorus through underground networks, reducing nutrient disparities among trees. The passage explicitly states that the researchers concluded fungal networks function as redistribution systems that reduce nutrient inequality. The choice claiming the study was the first to use isotope tagging is unsupported; the passage does not describe it as a first. The choice about trees in depleted soils growing more slowly contradicts the passage''s finding that fungi subsidize those trees. The choice about phosphorus being the most critical nutrient goes beyond the text, which examines phosphorus movement without ranking its importance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TFRGTF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The glass frog, native to Central and South American rainforests, has translucent skin on its underside that reveals its internal organs, including its beating heart. Scientists initially hypothesized that this transparency served primarily as camouflage against predators. __________ subsequent studies by Juan Manuel Guayasamin and colleagues demonstrated that the frogs achieve their remarkable transparency by sequestering nearly 89 percent of their red blood cells in their liver during sleep, a mechanism unrelated to predator evasion.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"However,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "However," because the passage shifts from an initial hypothesis (transparency as camouflage) to subsequent research findings that contradict that hypothesis (a mechanism unrelated to predator evasion). This contrast requires a transition signaling an opposing idea. "Furthermore," incorrectly suggests that the subsequent studies add to or reinforce the initial hypothesis, when they actually challenge it. "Similarly," wrongly implies the subsequent findings parallel the initial hypothesis. "For instance," incorrectly frames the subsequent research as an example supporting the camouflage hypothesis rather than as contradictory evidence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V6TFV8', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, physician Ignaz Semmelweis observed that women in maternity wards staffed by medical students died of puerperal fever at nearly five times the rate of those in wards staffed by midwives. He hypothesized that students carried infectious material from cadaver dissections to the delivery room. After Semmelweis instituted mandatory handwashing with chlorinated lime solution, the mortality rate in the student-staffed ward dropped from 18.3 percent to 1.3 percent. Despite this dramatic evidence, the medical establishment rejected Semmelweis''s findings for decades, partly because germ theory had not yet been formulated and the idea of invisible contagion seemed implausible.', $lyceon_json$[{"key":"A","text":"It presents an observation, describes a response to that observation, and then explains why that response was not widely accepted."},{"key":"B","text":"It introduces a scientific controversy, evaluates competing explanations, and then identifies which explanation ultimately prevailed."},{"key":"C","text":"It describes a medical procedure, critiques its effectiveness, and then proposes a more rigorous alternative."},{"key":"D","text":"It recounts a historical event, disputes the accuracy of traditional accounts, and then offers a revised interpretation."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the text presents an observation, describes a response, and explains why that response was not widely accepted. The passage follows exactly this structure: Semmelweis observes differential mortality rates, institutes handwashing as a response, and the final sentence explains the medical establishment''s rejection due to the absence of germ theory. The choice about evaluating competing explanations is wrong because the passage does not present rival hypotheses side by side. The choice about critiquing a procedure''s effectiveness is wrong because the passage shows handwashing was highly effective, not ineffective. The choice about disputing traditional accounts is wrong because the passage recounts history straightforwardly without challenging any prior narrative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VG9U25', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the text, what can most reasonably be inferred about the primary factor behind the increase in profit margins at the Covilhã mills?', E'Historian Luisa Ferreira has documented that Portuguese textile mills in the Covilhã region experienced a sharp labor shortage between 1891 and 1904, a period during which emigration to Brazil surged among young men from the surrounding villages. Mill owners responded by recruiting women and children as replacement workers, paying them roughly sixty percent of the wages previously earned by adult male workers. Ferreira notes that despite operating with a less experienced workforce earning lower wages, the mills'' total output declined by only four percent during this period, while their reported profit margins actually increased by eleven percent.', $lyceon_json$[{"key":"A","text":"The reduction in labor costs from paying lower wages to replacement workers more than offset the slight decline in output."},{"key":"B","text":"The mills introduced new steam-powered machinery during this period that dramatically increased per-worker productivity."},{"key":"C","text":"International demand for Portuguese textiles rose sharply between 1891 and 1904, driving up selling prices."},{"key":"D","text":"The Portuguese government provided subsidies to textile mills that employed women and children."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that reduced labor costs from lower wages offset the small output decline, explaining the profit increase. The passage specifies that replacement workers earned roughly sixty percent of prior wages while output fell only four percent — the cost savings logically exceeded the revenue loss. The choice about steam-powered machinery introduces a technological change the passage never mentions. The choice about rising international demand fabricates a market condition absent from the text. The choice about government subsidies invents a policy the passage does not reference. Each of these alternatives requires information not present in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VNBW5D', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support Sato''s hypothesis?', E'Marine biologist Kenji Sato hypothesizes that reef-building corals in the Ryukyu Islands have developed a tolerance for elevated sea temperatures compared to corals in other Indo-Pacific regions. To test this hypothesis, Sato''s team exposed coral fragments from seventeen Ryukyu reef sites to water temperatures of 31.7 degrees Celsius for forty-eight hours. Only two of the seventeen samples exhibited significant bleaching, while comparable experiments on corals from the Great Barrier Reef showed bleaching in eleven of fifteen samples at the same temperature.', $lyceon_json$[{"key":"A","text":"Ryukyu corals maintained higher photosynthetic rates than Great Barrier Reef corals when both were kept at 32.4 degrees Celsius for seventy-two hours."},{"key":"B","text":"Ryukyu corals and Great Barrier Reef corals exhibited identical bleaching rates when exposed to water at 27 degrees Celsius."},{"key":"C","text":"The species composition of Ryukyu reefs is similar to that of reefs in the central Indian Ocean."},{"key":"D","text":"Sea surface temperatures around the Ryukyu Islands have decreased by 0.3 degrees Celsius over the past decade."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that Ryukyu corals maintaining higher photosynthetic rates than Great Barrier Reef corals at an even higher temperature would directly support the claim of elevated heat tolerance. Identical bleaching rates at a moderate, non-stressful temperature would not differentiate the two populations and thus does not support the hypothesis. Similar species composition to Indian Ocean reefs addresses taxonomy rather than thermal tolerance. Decreasing sea surface temperatures around the Ryukyu Islands would actually complicate the hypothesis by reducing the selective pressure for heat tolerance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WHELB7', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the authors of Text 1 and Text 2 approach the topic of deep-sea mining?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y84IC0', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the text?', E'Literary scholars have long treated the unreliable narrator as a modernist innovation, citing works by Henry James and Ford Madox Ford as foundational examples. Yet the device appears with striking sophistication in Apuleius''s second-century Latin novel The Golden Ass, where the protagonist Lucius narrates events he cannot have witnessed and contradicts his own earlier claims without acknowledgment. This classical precedent complicates the standard genealogy by suggesting that narrative self-undermining is not a product of modern subjectivity but a recurring feature of fictional storytelling across vastly different cultural contexts.', $lyceon_json$[{"key":"A","text":"It supplies historical evidence that undermines the claim introduced in the first sentence."},{"key":"B","text":"It concedes a limitation in the author's argument before proceeding to the main thesis."},{"key":"C","text":"It defines a technical term that is essential for understanding the rest of the passage."},{"key":"D","text":"It illustrates a general principle that the first sentence has already established."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the second sentence supplies historical evidence undermining the first sentence''s claim. The first sentence presents the scholarly consensus that the unreliable narrator is a modernist innovation; the second sentence, introduced by "Yet," counters this by citing Apuleius''s second-century novel as a pre-modern example of the device. The choice about conceding a limitation is wrong because the second sentence challenges the established view rather than acknowledging a weakness in the author''s own position. The choice about defining a technical term is wrong because the second sentence provides a historical example, not a definition. The choice about illustrating a principle from the first sentence is wrong because the second sentence contradicts the first sentence''s claim rather than supporting it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YFQR2V', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the original 1847 lithograph by Honoré Daumier nor the later reproduction attributed to his apprentice _______ the satirical detail present in Daumier''s preliminary charcoal sketches, which were rediscovered in a Marseille archive in 2014.', $lyceon_json$[{"key":"A","text":"capture"},{"key":"B","text":"captures"},{"key":"C","text":"have captured"},{"key":"D","text":"are capturing"}]$lyceon_json$::jsonb, 'B', NULL, E'In a "neither...nor" construction, the verb agrees with the nearer subject. The nearer subject is "the later reproduction attributed to his apprentice," which is singular, so the verb must be singular: "captures." The plural "capture" would be incorrect because the verb must agree with the closer noun in a neither/nor construction. "Have captured" is both plural and uses present perfect tense, which conflicts with the passage''s use of simple present to describe a permanent characteristic of the artworks. "Are capturing" incorrectly uses the present progressive, suggesting an ongoing action rather than a permanent quality of the lithograph and reproduction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZHQKS8', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Geochemist Mira Castellano has challenged the prevailing model of Archean ocean chemistry by analyzing banded iron formations from the Pilbara Craton in Western Australia. The standard view holds that dissolved iron accumulated in anoxic deep oceans and precipitated when upwelling water encountered oxygen produced by cyanobacteria in surface layers. Castellano''s strontium isotope data, however, suggest that hydrothermal vents contributed iron to shallow marine environments at rates far exceeding what upwelling alone could explain. She argues that iron precipitation in the Pilbara was driven primarily by localized hydrothermal input rather than by ocean-wide upwelling, a distinction that, if confirmed, would require revising estimates of early atmospheric oxygen concentrations derived from banded iron formation models.', $lyceon_json$[{"key":"A","text":"Castellano's isotope evidence indicates that localized hydrothermal activity, not ocean-wide upwelling, primarily drove iron precipitation in the Pilbara, potentially undermining oxygen estimates based on existing models."},{"key":"B","text":"Castellano has proven that cyanobacteria played no role in the formation of banded iron deposits in the Pilbara Craton."},{"key":"C","text":"The standard model of Archean ocean chemistry has been universally abandoned in favor of Castellano's hydrothermal vent hypothesis."},{"key":"D","text":"Strontium isotope analysis is a more reliable geochemical technique than any method previously used to study banded iron formations."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that Castellano''s isotope evidence points to localized hydrothermal activity rather than ocean-wide upwelling as the primary driver of iron precipitation, with implications for atmospheric oxygen estimates. The passage presents Castellano''s work as a challenge to the prevailing model, not as proof that cyanobacteria had no role; the choice claiming she proved cyanobacteria irrelevant overstates her findings. The choice stating the standard model has been universally abandoned contradicts the passage''s conditional language (''if confirmed''). The choice about strontium isotope analysis being more reliable than all prior methods introduces a comparative claim the passage never makes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
